{
  "name": "opencode-smart-compact",
  "version": "0.1.0",
  "description": "OpenCode V2 plugin: verification-oriented smart compaction (Extract \u2192 Synthesize \u2192 Verify) with a configurable, cheaper compaction model. Port of pi-smart-compact's core.",
  "type": "module",
  "license": "MIT",
  "author": "Alper Tarhan <alper-tarhan@outlook.com>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/alpertarhan/opencode-smart-compact.git"
  },
  "homepage": "https://github.com/alpertarhan/opencode-smart-compact#readme",
  "bugs": {
    "url": "https://github.com/alpertarhan/opencode-smart-compact/issues"
  },
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "check": "bun run typecheck && bun test",
    "prepublishOnly": "bun run check"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "smart-compaction",
    "context-compression",
    "conversation-summarization"
  ],
  "devDependencies": {
    "typescript": "^5.6.0",
    "@types/bun": "^1.2.0"
  },
  "publishConfig": {
    "access": "public"
  }
}
